const templateRows = $input.all();

const targetRow = templateRows.find(function(item) {
  var label = item.json.col_1;
  return String(label).trim() === "2nd";
});

if (!targetRow) {
  throw new Error('Row with label "2nd" not found');
}

const templateColumnName = "1st follow-up sent 3 weeks after the initial request if there is no response or the information is not removed (check the site if not removed). ";
const template = targetRow.json[templateColumnName];

if (!template) {
  throw new Error('Template is empty. Available fields: ' + Object.keys(targetRow.json).join(', '));
}

const emails = $("Get many messages1").all();

return emails.map(function(email) {
  var emailData = email.json;
  var toEmail = "";
  if (emailData.to && emailData.to.value && emailData.to.value.length > 0) {
    toEmail = emailData.to.value[0].address;
  }

  // Extract Email ID directly from the subject line
  var subjectMatch = emailData.subject ? emailData.subject.match(/\[([A-Z0-9-]+)\]/) : null;
  var emailId = subjectMatch ? "ID-" + subjectMatch[1].replace(/^ID-/, "") : "";

  return {
    json: {
      to: toEmail,
      subject: emailData.subject,
      threadId: emailData.threadId,
      messageId: emailData.messageId,
      template: template,
      emailId: emailId
    }
  };
});

return items.map(function(item) {
  var data = item.json;

  var toEmail = data.to;
  var subject = data.subject;
  var messageId = data.messageId;
  var threadId = data.threadId;
  var emailId = data.emailId;

  var email = [
    "To: " + toEmail,
    "Subject: Re: " + subject,
    "In-Reply-To: " + messageId,
    "References: " + messageId,
    "Content-Type: text/plain; charset=UTF-8",
    "",
    data.template
  ].join("\n");

  var raw = Buffer.from(email).toString("base64")
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/, "");

  return {
    json: {
      raw: raw,
      threadId: threadId,
      emailId: emailId
    }
  };
});

