  const data = item.json;
  message += `${index + 1}. *Form:* ${data['Email/Form for submission']}\n`;
  message += `   *Custom removal link:* ${data.URL}\n`;
  message += `   *Owner:* ${data.Owner}\n\n`;
});

return [{
  json: {
    message: message
  }
}];

