const items = $input.all();
const allOrigItems = $("If 1st fu1").all();

// Build lookup from URL checker results (current batch only)
const statusMap = {};
items.forEach(item => {
  statusMap[item.json.url] = item.json.statusCode;
});

// Only return items that were in this batch
return allOrigItems
  .filter(original => statusMap.hasOwnProperty(original.json.URL))
  .map(original => {
    const data = original.json;
    const statusCode = statusMap[data.URL];
    return {
      json: {
        ...data,
        statusCode: statusCode,
        removed: [404, 410].includes(statusCode)
      }
    };
  });

const removedItems = $("If Removed 1st?").all();

let message = `✅ *Removal Confirmed*\n\n`;
message += `${removedItems.length} request(s) confirmed removed before 1st follow-up and closed:\n\n`;

removedItems.forEach((item, index) => {
  const data = item.json;
  message += `${index + 1}. *Form:* ${data['Email/Form for submission']}\n`;
  message += `   *Custom removal link:* ${data.URL}\n`;
  message += `   *Owner:* ${data.Owner}\n`;
  message += `   *Status code:* ${data.statusCode}\n\n`;
});

return [{
  json: {
    message: message
  }
}];

